ACCOUNTS_RELATIVE_PATH = "files/accounts"

#: File name of an account database inside its account directory.
DATABASE_FILE_NAME = "dc.db"

#: Database, relative to the application's data directory, holding the account
#: on builds that keep a single database rather than one per account.
DATABASE_RELATIVE_PATH = "databases/db.sqlite"

#: Directories searched for a task's note file, in the order they are tried.
DEFAULT_MARKOR_DIRS = (
    "/sdcard/Documents/markor",
    "/storage/emulated/0/Documents/markor",
    "/sdcard/Documents/QuickNote",
    "/storage/emulated/0/Documents/QuickNote",
    "/sdcard/Documents",
)

