PULL_TIMEOUT_SECONDS = 300.0


def normalize(text: Any) -> str:
    """Collapse whitespace in *text* and return it as a string."""
    if text is None:
        return ""
    return " ".join(str(text).split()).strip()


@dataclass(frozen=True)
class MarkorNote:
    """One note file found on the device."""

    path: str
    text: str
    size: int


class DeltaChatAndroidStore:
    """Reads a Delta Chat account and the note files a task produced.

    The account is read by copying the application's database off the device and
    querying it read-only; the notes are read by listing the directories the
    note editor writes to.
    """

    def __init__(
        self,
        controller: Any,
        *,
        app_package: str = DEFAULT_APP_PACKAGE,
        markor_package: str = DEFAULT_MARKOR_PACKAGE,
        markor_dirs: Sequence[str] | None = None,
    ) -> None:
        self.controller = controller
        self.app_package = str(app_package or DEFAULT_APP_PACKAGE)
        self.markor_package = str(markor_package or DEFAULT_MARKOR_PACKAGE)
        self.markor_dirs = tuple(markor_dirs or DEFAULT_MARKOR_DIRS)

    # ------------------------------------------------------------ plumbing
    def _require_controller(self) -> Any:
        if self.controller is None or not hasattr(self.controller, "execute_adb"):
            raise RuntimeError("an adb-capable controller is required to read Delta Chat state")
        return self.controller

    def database_path(self) -> str:
        """Return the on-device path of the account database.

        A release keeps one database per account under a directory named after
        the account; older releases keep a single file.  The account directories
        are listed on the device and the first database found is used, so the
        path does not depend on an account identifier being known in advance.
        """
        controller = self._require_controller()
        base = self._app_data_directory()
        accounts = f"{base}/{ACCOUNTS_RELATIVE_PATH}"
        listing = str(controller.execute_adb(["shell", "ls", accounts]) or "")
        for line in listing.splitlines():
            name = line.strip()
            if not name:
                continue
            candidate = f"{accounts}/{name}/{DATABASE_FILE_NAME}"
            probe = str(controller.execute_adb(["shell", "ls", candidate]) or "")
            if DATABASE_FILE_NAME in probe:
                return candidate
        return f"{base}/{DATABASE_RELATIVE_PATH}"

    def _app_data_directory(self) -> str:
        """Return the application's private data directory on the device."""
        controller = self._require_controller()
        output = str(
            controller.execute_adb(["shell", "run-as", self.app_package, "pwd"]) or ""
        ).strip()
        base = output.splitlines()[-1].strip() if output else ""
        if base.startswith("/"):
            return base
        return f"/data/data/{self.app_package}"

    def read_chat_messages(self) -> list[dict[str, Any]]:
        """Return every message the account holds, oldest first.

        Each record keeps the conversation it belongs to, its direction, its
        text and when it was sent, which is what the tasks describe.  The text
        column and the contact table differ between releases, so the columns
        that exist are read.
        """
        controller = self._require_controller()
        remote = self.database_path()
        with tempfile.TemporaryDirectory(prefix="deltachat-store-") as tmpdir:
            local = Path(tmpdir) / DATABASE_FILE_NAME
            controller.execute_adb(["pull", remote, str(local)])
            # Delta Chat uses SQLite WAL. The main database alone omits recent
            # messages, including agent actions. Copy its sidecars for read-only
            # evaluation against the current durable state.
            for suffix in ("-wal", "-shm"):
                controller.execute_adb(["pull", remote + suffix, str(local) + suffix])
            if not local.is_file() or local.stat().st_size == 0:
                raise RuntimeError(
                    f"the Delta Chat database could not be read from {remote}"
                )
            connection = sqlite3.connect(f"file:{local}?mode=ro", uri=True)
            try:
                connection.row_factory = sqlite3.Row
                message_columns = {
                    row[1] for row in connection.execute("PRAGMA table_info(msgs)")
                }
                chat_columns = {
                    row[1] for row in connection.execute("PRAGMA table_info(chats)")
                }
                text_column = next(
                    (name for name in ("txt", "text", "body") if name in message_columns),
                    "",
                )
                if not text_column:
                    raise RuntimeError(
                        "the Delta Chat message table carries no text column"
                    )
                selection = [
                    "m.id AS id",
                    "m.chat_id AS chat_id",
                    "m.from_id AS from_id",
                    "m.timestamp AS timestamp",
                    f"m.{text_column} AS text",
                    "m.type AS type",
                    "m.state AS state",
                ]
                if "name" in chat_columns:
                    selection.append("c.name AS chat_name")
                if "type" in chat_columns:
                    selection.append("c.type AS chat_type")
                chat_join = "LEFT JOIN chats c ON c.id = m.chat_id" if "name" in chat_columns else ""
                rows = connection.execute(
                    f"SELECT {', '.join(selection)} FROM msgs m {chat_join}"
                    " ORDER BY m.timestamp ASC, m.id ASC"
                ).fetchall()
                contacts: dict[Any, str] = {}
                if "from_id" in message_columns:
                    contact_columns = {
                        row[1] for row in connection.execute("PRAGMA table_info(contacts)")
                    }
                    if {"id", "name"} <= contact_columns:
                        label = "name" if "addr" not in contact_columns else "COALESCE(name, addr)"
                        contacts = {
                            row["id"]: row["label"] or ""
                            for row in connection.execute(
                                f"SELECT id, {label} AS label FROM contacts"
                            ).fetchall()
                        }
            finally:
                connection.close()

        messages: list[dict[str, Any]] = []
        for row in rows:
            keys = set(row.keys())
            messages.append(
                {
                    "id": row["id"],
                    "chat_id": row["chat_id"],
                    "chat_name": normalize(row["chat_name"]) if "chat_name" in keys else "",
                    "chat_type": row["chat_type"] if "chat_type" in keys else None,
                    "from_id": row["from_id"],
                    "from_name": normalize(contacts.get(row["from_id"], "")),
                    "timestamp": row["timestamp"],
                    "text": str(row["text"] or ""),
                    "type": row["type"],
                    "state": row["state"],
                    "outgoing": bool(row["from_id"] == 1),
                }
            )
        return messages

    def read_chats(self) -> list[dict[str, Any]]:
        """Return every conversation the account holds.

        The columns a conversation carries differ between releases, so the
        columns that exist are read and the rest are reported as absent rather
        than as empty: a description that the schema cannot hold is not the same
        as a conversation whose description is blank.
        """
        controller = self._require_controller()
        remote = self.database_path()
        with tempfile.TemporaryDirectory(prefix="deltachat-chats-") as tmpdir:
            local = Path(tmpdir) / "db.sqlite"
            controller.execute_adb(["pull", remote, str(local)])
            for suffix in ("-wal", "-shm"):
                controller.execute_adb(["pull", remote + suffix, str(local) + suffix])
            if not local.is_file() or local.stat().st_size == 0:
                raise RuntimeError(
                    f"the Delta Chat database could not be read from {remote}"
                )
            connection = sqlite3.connect(f"file:{local}?mode=ro", uri=True)
            try:
                connection.row_factory = sqlite3.Row
                columns = {
                    row[1] for row in connection.execute("PRAGMA table_info(chats)")
                }
                wanted = ["id", "name", "type", "grpid", "description", "archived"]
                selected = [column for column in wanted if column in columns]
                rows = connection.execute(
                    f"SELECT {', '.join(selected)} FROM chats ORDER BY id ASC"
                ).fetchall()
                descriptions = {}
                if connection.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='chats_descriptions'").fetchone():
                    descriptions = {row[0]: row[1] for row in connection.execute("SELECT chat_id, description FROM chats_descriptions")}
            finally:
                connection.close()
        records = [{column: row[column] for column in selected} for row in rows]
        for record in records:
            if not record.get('description') and record.get('id') in descriptions:
                record['description'] = descriptions[record['id']]
        return records

    # ------------------------------------------------------------- notes
    def read_notes(self) -> list[MarkorNote]:
        """Return every note file found in the editor's directories."""
        controller = self._require_controller()
        found: list[MarkorNote] = []
        seen: set[str] = set()
        for directory in self.markor_dirs:
            listing = str(
                controller.execute_adb(
                    [
                        "shell",
                        "ls",
                        "-1",
                        "-p",
                        shlex.quote(directory),
                    ]
                )
                or ""
            )
            for line in listing.splitlines():
                name = line.strip()
                if not name or name.endswith("/"):
                    continue
                if not name.lower().endswith((".md", ".markor", ".txt")):
                    continue
                remote = f"{directory.rstrip('/')}/{name}"
                canonical = remote.replace("/sdcard/", "/storage/emulated/0/", 1)
                if canonical in seen:
                    continue
                seen.add(canonical)
                text = str(controller.execute_adb(["shell", "cat", shlex.quote(remote)]) or "")
                found.append(
                    MarkorNote(path=remote, text=text, size=len(text.encode("utf-8")))
                )
        return found

    def find_note(self, filename: str) -> list[MarkorNote]:
        """Return the notes whose file name matches *filename* exactly."""
        stem = filename[:-3] if filename.lower().endswith(".md") else filename
        wanted = {filename, f"{stem}.md", f"{stem}.txt"}
        return [
            note
            for note in self.read_notes()
            if Path(note.path).name in wanted
        ]


def message_text_includes(messages: Sequence[Mapping[str, Any]], needle: str) -> list[Mapping[str, Any]]:
    """Return the messages whose text contains *needle*, case-sensitively."""
    return [
        message
        for message in messages
        if needle and needle in str(message.get("text") or "")
    ]


def chat_named(chats: Sequence[Mapping[str, Any]], name: str) -> list[Mapping[str, Any]]:
    """Return the conversations whose name matches *name* exactly."""
    return [chat for chat in chats if normalize(chat.get("name")) == name]


